# =============================================================================# SETUP RCLONE + GOOGLE DRIVE - SIMPEG BACKUP# Jalankan script ini SEKALI untuk konfigurasi awal# =============================================================================Write-Host "================================================" -ForegroundColor CyanWrite-Host "     SETUP RCLONE + GOOGLE DRIVE               " -ForegroundColor CyanWrite-Host "================================================" -ForegroundColor CyanWrite-Host ""$RcloneDir  = "C:\rclone"$RclonePath = "$RcloneDir\rclone.exe"$RcloneZip  = "$env:TEMP\rclone.zip"$RcloneUrl  = "https://downloads.rclone.org/rclone-current-windows-amd64.zip"# --- LANGKAH 1: Download rclone ---if (-not (Test-Path $RclonePath)) {    Write-Host "[1/3] Mendownload rclone..." -ForegroundColor Yellow    if (-not (Test-Path $RcloneDir)) { New-Item -ItemType Directory -Path $RcloneDir -Force | Out-Null }    try {        Invoke-WebRequest -Uri $RcloneUrl -OutFile $RcloneZip -UseBasicParsing        Write-Host "      Download selesai." -ForegroundColor Green        # Extract        Write-Host "      Mengekstrak..." -ForegroundColor Yellow        $extractTemp = "$env:TEMP\rclone-extract"        Expand-Archive -Path $RcloneZip -DestinationPath $extractTemp -Force        $rcloneExe = Get-ChildItem -Path $extractTemp -Recurse -Filter "rclone.exe" | Select-Object -First 1        Copy-Item -Path $rcloneExe.FullName -Destination $RclonePath -Force        Remove-Item -Path $extractTemp -Recurse -Force        Remove-Item -Path $RcloneZip -Force        Write-Host "[OK] rclone berhasil diinstall di $RclonePath" -ForegroundColor Green    } catch {        Write-Host "[ERROR] Gagal mendownload rclone: $_" -ForegroundColor Red        Write-Host "        Download manual dari: https://rclone.org/downloads/" -ForegroundColor Yellow        exit 1    }} else {    Write-Host "[SKIP] rclone sudah ada di $RclonePath" -ForegroundColor Yellow}Write-Host ""# --- LANGKAH 2: Konfigurasi Google Drive ---Write-Host "[2/3] Konfigurasi Google Drive..." -ForegroundColor YellowWrite-Host ""Write-Host "  Browser akan terbuka untuk meminta izin ke Google Drive Anda." -ForegroundColor WhiteWrite-Host "  Ikuti instruksi berikut:" -ForegroundColor WhiteWrite-Host "    1. Ketik 'n' (new remote) lalu Enter" -ForegroundColor CyanWrite-Host "    2. Ketik nama remote: gdrive  lalu Enter" -ForegroundColor CyanWrite-Host "    3. Pilih 'drive' (Google Drive) - ketik nomor yang sesuai lalu Enter" -ForegroundColor CyanWrite-Host "    4. Biarkan kosong Client ID dan Secret (tekan Enter)" -ForegroundColor CyanWrite-Host "    5. Pilih scope '1' (akses penuh ke Drive) lalu Enter" -ForegroundColor CyanWrite-Host "    6. Biarkan kosong root_folder_id dan service_account (tekan Enter)" -ForegroundColor CyanWrite-Host "    7. Ketik 'n' (No advanced config) lalu Enter" -ForegroundColor CyanWrite-Host "    8. Ketik 'y' (Yes use auto config) lalu Enter" -ForegroundColor CyanWrite-Host "    9. Login di browser yang terbuka dengan akun Google Anda" -ForegroundColor CyanWrite-Host "   10. Kembali ke terminal, ketik 'n' (not team drive) lalu Enter" -ForegroundColor CyanWrite-Host "   11. Ketik 'y' untuk konfirmasi lalu Enter" -ForegroundColor CyanWrite-Host "   12. Ketik 'q' untuk keluar lalu Enter" -ForegroundColor CyanWrite-Host ""$confirm = Read-Host "Tekan ENTER untuk mulai konfigurasi Google Drive..."& $RclonePath configWrite-Host ""# --- LANGKAH 3: Test koneksi ---Write-Host "[3/3] Testing koneksi ke Google Drive..." -ForegroundColor Yellowtry {    $result = & $RclonePath lsd gdrive: 2>&1    if ($LASTEXITCODE -eq 0) {        Write-Host "[OK] Koneksi ke Google Drive BERHASIL!" -ForegroundColor Green        Write-Host "     Folder di Google Drive Anda:" -ForegroundColor White        Write-Host $result    } else {        Write-Host "[WARNING] Test koneksi gagal. Cek konfigurasi rclone." -ForegroundColor Red    }} catch {    Write-Host "[WARNING] Tidak bisa test koneksi: $_" -ForegroundColor Yellow}Write-Host ""Write-Host "================================================" -ForegroundColor CyanWrite-Host " SETUP RCLONE SELESAI!" -ForegroundColor GreenWrite-Host "================================================" -ForegroundColor CyanWrite-Host ""Write-Host "Untuk test sync manual, jalankan:" -ForegroundColor WhiteWrite-Host "  C:\rclone\rclone.exe sync C:\simpeg-backup gdrive:simpeg-backup --progress" -ForegroundColor Cyan